  const[savedSnapshot,setSavedSnapshot]=useState(""),[undoStack,setUndoStack]=useState<SiteBuilderState[]>([]),[redoStack,setRedoStack]=useState<SiteBuilderState[]>([]),[notice,setNotice]=useState(""),[saving,setSaving]=useState(false),[publishing,setPublishing]=useState(false),[uploading,setUploading]=useState(false),[canPublish,setCanPublish]=useState(false);
  const[showLibrary,setShowLibrary]=useState(false),[showNewPage,setShowNewPage]=useState(false),[newPageName,setNewPageName]=useState(""),[showHistory,setShowHistory]=useState(false),[history,setHistory]=useState<SiteBuilderRevisionMeta[]>([]),[restoring,setRestoring]=useState(false);
  const[frameHeight,setFrameHeight]=useState(900),[scale,setScale]=useState(1);
  const frameRef=useRef<HTMLIFrameElement>(null),hostRef=useRef<HTMLDivElement>(null);

  useEffect(()=>{void load()},[]);
  async function load(){try{const[builderRes,mediaRes]=await Promise.all([fetch("/admin/api/site-builder",{cache:"no-store"}),fetch("/admin/api/media",{cache:"no-store"})]);if(!builderRes.ok)throw new Error("Website Studio konnte nicht geladen werden.");const builder=await builderRes.json() as LoadResponse;const mediaBody=mediaRes.ok?await mediaRes.json() as {items?:MediaItem[]}:{items:[]};setState(builder.state);setPublished(builder.published);setSavedSnapshot(JSON.stringify(builder.state));setCanPublish(Boolean(builder.permissions?.canPublish));setMedia(mediaBody.items||[]);const first=builder.state.pages[0];setPageId(first?.id||"");setSectionId(first?.sections[0]?.id||"")}catch(error){setNotice(error instanceof Error?error.message:"Fehler beim Laden")}}

  const page=useMemo(()=>state?.pages.find(item=>item.id===pageId)||state?.pages[0],[state,pageId]);
  const section=useMemo(()=>page?.sections.find(item=>item.id===sectionId)||page?.sections[0],[page,sectionId]);
  const dirty=!!state&&JSON.stringify(state)!==savedSnapshot;
  const hasUnpublished=!!state&&!!published&&JSON.stringify(state)!==JSON.stringify(published);
  const duplicateSlug=!!state&&state.pages.some((candidate,index)=>state.pages.findIndex(item=>item.slug.trim().toLowerCase()===candidate.slug.trim().toLowerCase())!==index);
  const viewportWidth=previewWidths[mode];

  useEffect(()=>{const host=hostRef.current;if(!host)return;const resize=()=>setScale(Math.min(1,Math.max(.2,(host.clientWidth-8)/viewportWidth)));resize();const observer=new ResizeObserver(resize);observer.observe(host);return()=>observer.disconnect()},[viewportWidth]);
  const sendState=()=>{if(!state||!pageId)return;frameRef.current?.contentWindow?.postMessage({type:"rascals-studio-state",state,pageId},window.location.origin)};
  useEffect(()=>{sendState()},[state,pageId]);
  useEffect(()=>{const handler=(event:MessageEvent)=>{if(event.origin!==window.location.origin)return;const data=event.data as {type?:string;height?:number;sectionId?:string;elementKey?:string;theme?:string};if(data.type==="rascals-studio-ready")sendState();if(data.type==="rascals-studio-height"&&typeof data.height==="number")setFrameHeight(Math.max(500,data.height));if(data.type==="rascals-studio-select"){if(data.theme){setInspectorMode("theme");setSelectedElement("");return}if(data.sectionId){setSectionId(data.sectionId);setInspectorMode("section");if(data.elementKey){setSelectedElement(data.elementKey);setTab("element")}else{setSelectedElement("");setTab("content")}}}};window.addEventListener("message",handler);return()=>window.removeEventListener("message",handler)},[state,pageId]);

  function commit(next:SiteBuilderState){if(!state)return;if(JSON.stringify(state)===JSON.stringify(next))return;setUndoStack(current=>[...current.slice(-49),clone(state)]);setRedoStack([]);setState(next)}
  function commitWith(updater:(current:SiteBuilderState)=>SiteBuilderState){if(state)commit(updater(state))}
  function undo(){if(!state||!undoStack.length)return;const previous=undoStack.at(-1)!;setRedoStack(current=>[clone(state),...current].slice(0,50));setUndoStack(current=>current.slice(0,-1));setState(clone(previous))}
  function redo(){if(!state||!redoStack.length)return;const next=redoStack[0];setUndoStack(current=>[...current.slice(-49),clone(state)]);setRedoStack(current=>current.slice(1));setState(clone(next))}
  function patchPage(patch:Partial<BuilderPage>){if(!page)return;commitWith(current=>({...current,pages:current.pages.map(item=>item.id===page.id?{...item,...patch}:item)}))}
  function patchSection(patch:Partial<BuilderSection>){if(!page||!section)return;commitWith(current=>({...current,pages:current.pages.map(p=>p.id===page.id?{...p,sections:p.sections.map(item=>item.id===section.id?{...item,...patch}:item)}:p)}))}
  function patchSectionStyle(patch:Partial<BuilderSectionStyle>){if(!section)return;patchSection({style:{...section.style,...patch}})}
  function patchResponsive(device:"tablet"|"mobile",patch:Partial<BuilderResponsiveStyle>){if(!section)return;patchSectionStyle({[device]:{...(section.style[device]||{}),...patch}})}
  function patchItem(id:string,patch:Partial<BuilderItem>){if(!section)return;patchSection({items:section.items.map(item=>item.id===id?{...item,...patch}:item)})}
  function patchTheme(patch:Partial<SiteBuilderState["theme"]>){commitWith(current=>({...current,theme:{...current.theme,...patch}}))}
  function patchElementStyle(key:string,patch:Partial<BuilderElementStyle>,device:PreviewMode="desktop"){if(!section)return;const parsed=getItemAndField(section,key);if(parsed){const currentStyle=parsed.item.elementStyles?.[parsed.field]||{};const nextStyle=device==="desktop"?{...currentStyle,...patch}:{...currentStyle,[device]:{...(currentStyle[device]||{}),...(patch as BuilderElementResponsiveStyle)}};patchItem(parsed.item.id,{elementStyles:{...(parsed.item.elementStyles||{}),[parsed.field]:nextStyle}});return}const currentStyle=section.elementStyles?.[key]||{};const nextStyle=device==="desktop"?{...currentStyle,...patch}:{...currentStyle,[device]:{...(currentStyle[device]||{}),...(patch as BuilderElementResponsiveStyle)}};patchSection({elementStyles:{...(section.elementStyles||{}),[key]:nextStyle}})}
  function patchElementContent(key:string,value:string,url?:string){if(!section)return;const parsed=getItemAndField(section,key);if(parsed){const field=parsed.field;if(field==="link")patchItem(parsed.item.id,{linkLabel:value,linkUrl:url??parsed.item.linkUrl});else if(field==="image")patchItem(parsed.item.id,{image:value});else if(field==="icon")patchItem(parsed.item.id,{icon:value});else patchItem(parsed.item.id,{[field]:value} as Partial<BuilderItem>);return}if(key==="button")patchSection({buttonLabel:value,buttonUrl:url??section.buttonUrl});else if(key==="image")patchSection({image:value});else patchSection({[key]:value} as Partial<BuilderSection>)}

  function selectPage(id:string){if(!state)return;const next=state.pages.find(item=>item.id===id);if(!next)return;setPageId(id);setSectionId(next.sections[0]?.id||"");setSelectedElement("");setInspectorMode(next.sections.length?"section":"page");setTab("content")}
  function addSection(type:BuilderSectionType){if(!page)return;if(dynamicTypes.has(type)){const existing=page.sections.find(item=>item.type===type);if(existing){setSectionId(existing.id);setInspectorMode("section");setShowLibrary(false);setNotice(`${typeLabel(type)} ist auf dieser Seite bereits vorhanden.`);return}}const next=freshSection(type);patchPage({sections:[...page.sections,next]});setSectionId(next.id);setSelectedElement("");setInspectorMode("section");setTab("content");setShowLibrary(false)}
  function duplicateSection(){if(!page||!section)return;if(dynamicTypes.has(section.type)){setNotice(`${typeLabel(section.type)} kann nur einmal pro Seite verwendet werden.`);return}const copy={...clone(section),id:crypto.randomUUID(),items:section.items.map(item=>({...clone(item),id:crypto.randomUUID()}))};const index=page.sections.findIndex(item=>item.id===section.id);const sections=[...page.sections];sections.splice(index+1,0,copy);patchPage({sections});setSectionId(copy.id);setSelectedElement("")}
  function deleteSection(){if(!page||!section||!confirm("Abschnitt wirklich löschen?"))return;const sections=page.sections.filter(item=>item.id!==section.id);patchPage({sections});setSectionId(sections[0]?.id||"");setSelectedElement("")}
  function moveSection(direction:-1|1){if(!page||!section)return;const index=page.sections.findIndex(item=>item.id===section.id),target=index+direction;if(target<0||target>=page.sections.length)return;const sections=[...page.sections];[sections[index],sections[target]]=[sections[target],sections[index]];patchPage({sections})}
  function createPage(){if(!state)return;const name=newPageName.trim()||"Neue Seite",base=slugify(name)||`seite-${state.pages.length+1}`;let slug=base,count=2;while(state.pages.some(item=>item.slug===slug))slug=`${base}-${count++}`;const first=freshSection("hero");const next:BuilderPage={id:crypto.randomUUID(),name,slug,enabled:false,showInNav:false,navLabel:name,title:name,description:"",sections:[first]};commit({...state,pages:[...state.pages,next]});setPageId(next.id);setSectionId(first.id);setSelectedElement("");setInspectorMode("page");setShowNewPage(false);setNewPageName("")}
  function deletePage(){if(!state||!page||page.slug===""||!confirm(`Seite „${page.name}“ wirklich löschen?`))return;const pages=state.pages.filter(item=>item.id!==page.id);commit({...state,pages});const next=pages[0];setPageId(next?.id||"");setSectionId(next?.sections[0]?.id||"");setSelectedElement("")}
  function duplicatePage(){if(!state||!page)return;const base=`${page.slug||"startseite"}-kopie`;let slug=base,count=2;while(state.pages.some(item=>item.slug===slug))slug=`${base}-${count++}`;const copy:BuilderPage={...clone(page),id:crypto.randomUUID(),name:`${page.name} Kopie`,slug,enabled:false,showInNav:false,sections:page.sections.map(item=>({...clone(item),id:crypto.randomUUID(),items:item.items.map(child=>({...clone(child),id:crypto.randomUUID()}))}))};commit({...state,pages:[...state.pages,copy]});setPageId(copy.id);setSectionId(copy.sections[0]?.id||"");setInspectorMode("page")}
  function movePage(direction:-1|1){if(!state||!page)return;const index=state.pages.findIndex(item=>item.id===page.id),target=index+direction;if(target<0||target>=state.pages.length)return;const pages=[...state.pages];[pages[index],pages[target]]=[pages[target],pages[index]];commit({...state,pages})}
  async function uploadImage(event:ChangeEvent<HTMLInputElement>,apply:(url:string)=>void){const file=event.target.files?.[0];if(!file)return;setUploading(true);try{const data=new FormData();data.append("file",file);const response=await fetch("/admin/api/media",{method:"POST",body:data});const body=await response.json() as {url?:string;key?:string;error?:string};if(!response.ok||!body.url)throw new Error(body.error||"Upload fehlgeschlagen");apply(body.url);if(body.key)setMedia(current=>[{key:body.key!,url:body.url!},...current.filter(item=>item.key!==body.key)]);setNotice("Bild hochgeladen.")}catch(error){setNotice(error instanceof Error?error.message:"Upload fehlgeschlagen")}finally{setUploading(false);event.target.value=""}}
  async function saveDraft(){if(!state||duplicateSlug)return;setSaving(true);try{const response=await fetch("/admin/api/site-builder",{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify({...state,editorInitialized:true})});const body=await response.json() as {state?:SiteBuilderState;error?:string};if(!response.ok||!body.state)throw new Error(body.error||"Speichern fehlgeschlagen");setState(body.state);setSavedSnapshot(JSON.stringify(body.state));setNotice("Entwurf gespeichert.")}catch(error){setNotice(error instanceof Error?error.message:"Speichern fehlgeschlagen")}finally{setSaving(false)}}
  async function publish(){if(!state||!canPublish||duplicateSlug)return;setPublishing(true);try{const response=await fetch("/admin/api/site-builder/publish",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({state:{...state,editorInitialized:true}})});const body=await response.json() as {state?:SiteBuilderState;error?:string};if(!response.ok||!body.state)throw new Error(body.error||"Veröffentlichen fehlgeschlagen");setState(body.state);setPublished(clone(body.state));setSavedSnapshot(JSON.stringify(body.state));setNotice("Website veröffentlicht.")}catch(error){setNotice(error instanceof Error?error.message:"Veröffentlichen fehlgeschlagen")}finally{setPublishing(false)}}
