  async function restoreRevision(id:string){if(restoring)return;setRestoring(true);try{const response=await fetch("/admin/api/site-builder/history",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({revisionId:id})});const body=await response.json() as {state?:SiteBuilderState;error?:string};if(!response.ok||!body.state)throw new Error(body.error||"Version konnte nicht wiederhergestellt werden.");setState(body.state);setSavedSnapshot(JSON.stringify(body.state));setUndoStack([]);setRedoStack([]);const first=body.state.pages[0];setPageId(first?.id||"");setSectionId(first?.sections[0]?.id||"");setSelectedElement("");setShowHistory(false);setNotice("Version als Entwurf wiederhergestellt.")}catch(error){setNotice(error instanceof Error?error.message:"Wiederherstellen fehlgeschlagen")}finally{setRestoring(false)}}

